-- FSQA risk classifications are explicit auditor assessments, separate from the audit score.
alter table public.retail_cpar_items add column if not exists risk_level text check(risk_level in ('low','medium','high','critical'));
alter table public.retail_cpar_updates drop constraint if exists retail_cpar_updates_kind_check;
alter table public.retail_cpar_updates add constraint retail_cpar_updates_kind_check check(kind in ('update','submitted','acknowledged','returned','verified','risk_assessed'));

do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$('review_access','auditor_logout','assess_risk','acknowledged'$old$ in definition)=0 then definition:=replace(definition,$old$('review_access','auditor_logout','acknowledged'$old$,$new$('review_access','auditor_logout','assess_risk','acknowledged'$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$insert into public.retail_cpar_items(audit_id,item_key,finding,risk_level) values(a.id,(x->>'s')||':'||(x->>'i'),x,case when x->>'risk_level' in ('low','medium','high','critical') then x->>'risk_level' else null end)$old$ in definition)=0 then definition:=replace(definition,$old$insert into public.retail_cpar_items(audit_id,item_key,finding) values(a.id,(x->>'s')||':'||(x->>'i'),x)$old$,$new$insert into public.retail_cpar_items(audit_id,item_key,finding,risk_level) values(a.id,(x->>'s')||':'||(x->>'i'),x,case when x->>'risk_level' in ('low','medium','high','critical') then x->>'risk_level' else null end)$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$   if upper(coalesce(x->>'section','')) like '%FOOD SAFETY%' and x->>'result' in ('action','noncompliant') and coalesce(x->>'risk_level','') not in ('low','medium','high','critical') then raise exception 'Select an FSQA risk level for each FSQA finding';end if;
   if x->>'result'<>'na' then$old$ in definition)=0 then definition:=replace(definition,$old$   if x->>'result'<>'na' then$old$,$new$   if upper(coalesce(x->>'section','')) like '%FOOD SAFETY%' and x->>'result' in ('action','noncompliant') and coalesce(x->>'risk_level','') not in ('low','medium','high','critical') then raise exception 'Select an FSQA risk level for each FSQA finding';end if;
   if x->>'result'<>'na' then$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$ if p_action='assess_risk' then
  if upper(coalesce(c.finding->>'section','')) not like '%FOOD SAFETY%' then raise exception 'Risk levels apply to the FSQA category';end if;
  if exists(select 1 from public.retail_cpar_closures where audit_id=c.audit_id) then raise exception 'This CPAR is already closed';end if;
  if coalesce(p_data->>'risk_level','') not in ('low','medium','high','critical') then raise exception 'Choose Low, Medium, High or Critical';end if;
  update public.retail_cpar_items set risk_level=p_data->>'risk_level' where id=c.id;
  insert into public.retail_cpar_updates(item_id,request_key,kind,actor,remarks) values(c.id,gen_random_uuid(),'risk_assessed',v_reviewer,'FSQA risk level: '||upper(p_data->>'risk_level'));
  return jsonb_build_object('risk_level',p_data->>'risk_level','auditor_name',v_reviewer);
 end if;
 if p_action in ('update','submitted','acknowledged','returned','verified') then$old$ in definition)=0 then definition:=replace(definition,$old$ if p_action in ('update','submitted','acknowledged','returned','verified') then$old$,$new$ if p_action='assess_risk' then
  if upper(coalesce(c.finding->>'section','')) not like '%FOOD SAFETY%' then raise exception 'Risk levels apply to the FSQA category';end if;
  if exists(select 1 from public.retail_cpar_closures where audit_id=c.audit_id) then raise exception 'This CPAR is already closed';end if;
  if coalesce(p_data->>'risk_level','') not in ('low','medium','high','critical') then raise exception 'Choose Low, Medium, High or Critical';end if;
  update public.retail_cpar_items set risk_level=p_data->>'risk_level' where id=c.id;
  insert into public.retail_cpar_updates(item_id,request_key,kind,actor,remarks) values(c.id,gen_random_uuid(),'risk_assessed',v_reviewer,'FSQA risk level: '||upper(p_data->>'risk_level'));
  return jsonb_build_object('risk_level',p_data->>'risk_level','auditor_name',v_reviewer);
 end if;
 if p_action in ('update','submitted','acknowledged','returned','verified') then$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$   if p_action='verified' and upper(coalesce(c.finding->>'section','')) like '%FOOD SAFETY%' and coalesce(c.risk_level,c.finding->>'risk_level','')='' then raise exception 'Assess the FSQA risk level before approving this action';end if;
   if c.status not in ('submitted','acknowledged')$old$ in definition)=0 then definition:=replace(definition,$old$   if c.status not in ('submitted','acknowledged')$old$,$new$   if p_action='verified' and upper(coalesce(c.finding->>'section','')) like '%FOOD SAFETY%' and coalesce(c.risk_level,c.finding->>'risk_level','')='' then raise exception 'Assess the FSQA risk level before approving this action';end if;
   if c.status not in ('submitted','acknowledged')$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$  if exists(select 1 from public.retail_cpar_items where audit_id=aid and upper(coalesce(finding->>'section','')) like '%FOOD SAFETY%' and coalesce(risk_level,finding->>'risk_level','')='') then raise exception 'Assess FSQA risk levels before final approval';end if;
  if length(trim(coalesce(p_data->>'comments','')))=0$old$ in definition)=0 then definition:=replace(definition,$old$  if length(trim(coalesce(p_data->>'comments','')))=0$old$,$new$  if exists(select 1 from public.retail_cpar_items where audit_id=aid and upper(coalesce(finding->>'section','')) like '%FOOD SAFETY%' and coalesce(risk_level,finding->>'risk_level','')='') then raise exception 'Assess FSQA risk levels before final approval';end if;
  if length(trim(coalesce(p_data->>'comments','')))=0$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure); if position($old$'finding',i.finding,'status',i.status,'risk_level',i.risk_level,$old$ in definition)=0 then definition:=replace(definition,$old$'finding',i.finding,'status',i.status,$old$,$new$'finding',i.finding,'status',i.status,'risk_level',i.risk_level,$new$);execute definition;end if;end $change$;